// Parse Message — n8n Code Node (FIRST node in JS-01v2).
//
// Extracts phone + text from the WhatsApp Cloud API webhook payload and assigns
// ONE trace_id (UUIDv7) per inbound message. Uses the SAME robust extraction as
// JS-01 (handles entry→changes→value unwrap AND the already-unwrapped shape the
// n8n WhatsApp Trigger delivers), then adds v1.1 fields: trace_id, lowercased
// `text` (for keyword routing) + case-preserved `original_text` (for ticket regex).
//
// Self-contained (n8n sandbox: no import/require). Emits ONE item per text
// message; skips status callbacks and non-text messages.

const UUID7_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function isUuid7(s) { return typeof s === 'string' && UUID7_RE.test(s); }
function randomBytes(out) {
  const g = (typeof globalThis !== 'undefined') ? globalThis : {};
  if (g.crypto && typeof g.crypto.getRandomValues === 'function') { g.crypto.getRandomValues(out); return out; }
  for (let i = 0; i < out.length; i++) out[i] = Math.floor(Math.random() * 256);
  return out;
}
const HEX = [];
for (let i = 0; i < 256; i++) HEX.push((i + 256).toString(16).slice(1));
function uuid7(now) {
  if (now == null) now = Date.now();
  const b = new Uint8Array(16);
  const ts = Math.max(0, Math.floor(now));
  b[0] = Math.floor(ts / 1099511627776) & 255;
  b[1] = Math.floor(ts / 4294967296) & 255;
  b[2] = Math.floor(ts / 16777216) & 255;
  b[3] = Math.floor(ts / 65536) & 255;
  b[4] = Math.floor(ts / 256) & 255;
  b[5] = ts & 255;
  const rand = randomBytes(new Uint8Array(10));
  for (let i = 0; i < 10; i++) b[6 + i] = rand[i];
  b[6] = (b[6] & 15) | 112;
  b[8] = (b[8] & 63) | 128;
  return (
    HEX[b[0]] + HEX[b[1]] + HEX[b[2]] + HEX[b[3]] + '-' +
    HEX[b[4]] + HEX[b[5]] + '-' +
    HEX[b[6]] + HEX[b[7]] + '-' +
    HEX[b[8]] + HEX[b[9]] + '-' +
    HEX[b[10]] + HEX[b[11]] + HEX[b[12]] + HEX[b[13]] + HEX[b[14]] + HEX[b[15]]
  );
}
function inboundTraceId(m) {
  const headers = (m && (m.headers || m.header)) || (m && m.body && m.body.headers);
  if (headers && typeof headers === 'object') {
    for (const k of Object.keys(headers)) {
      if (k.toLowerCase() === 'x-trace-id' && isUuid7(String(headers[k]).trim())) return String(headers[k]).trim();
    }
  }
  if (m && isUuid7(String(m.trace_id || '').trim())) return String(m.trace_id).trim();
  return null;
}

const items = $input.all();
const out = [];
for (const it of items) {
  const raw = (it.json && it.json.body) || it.json || {};
  let body = raw;
  // Unwrap the full Cloud-API envelope if present (entry → changes → value).
  if (raw.entry && Array.isArray(raw.entry)) {
    for (const entry of raw.entry) {
      for (const change of (entry.changes || [])) {
        if (change.field === 'messages' && change.value) { body = change.value; break; }
      }
    }
  }
  // Skip delivery/read status callbacks (no user message).
  if (body.statuses && !body.messages) continue;
  if (!body.messages || body.messages.length === 0) continue;

  for (const msg of body.messages) {
    // Accept text messages and interactive (button/list) replies.
    let rawText = '';
    if (msg.type === 'text' && msg.text && msg.text.body) rawText = msg.text.body;
    else if (msg.type === 'interactive' && msg.interactive) {
      const inter = msg.interactive;
      rawText = (inter.button_reply && (inter.button_reply.id || inter.button_reply.title))
        || (inter.list_reply && (inter.list_reply.id || inter.list_reply.title)) || '';
    } else if (msg.button && msg.button.text) rawText = msg.button.text;
    rawText = (rawText || '').trim();
    if (!rawText) continue;

    const phone = msg.from || body.from || '';
    const trace_id = inboundTraceId(it.json) || uuid7();

    out.push({
      json: {
        phone,
        message: { text: rawText.toLowerCase(), original_text: rawText },
        trace_id,
        message_id: msg.id || null,
        raw: it.json,
      },
    });
  }
}

// Defensive: if nothing parsed, still emit a single empty item so downstream
// nodes fail gracefully rather than the workflow stopping with 0 items.
if (out.length === 0) {
  return [{ json: { phone: '', message: { text: '', original_text: '' }, trace_id: uuid7(), skip: true } }];
}
return out;

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/prepare-context.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Prepare Context' -> prepare-context.js)
return [$input.first()];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/ceo-router.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'CEO Router' -> ceo-router.js)
// Output contract consumed by Switch Node: $json.agent in {complaint,blood,donor,info,welcome}
return [{ json: { ...$json, agent: 'welcome', reason: 'placeholder' } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/gemini-substitute.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Gemini Check - Complaint' -> gemini-substitute.js)
// Task 27.4 — Design §v1.1.10 Circuit Breakers (Req 29.2, 29.3)
// Reads circuit_state.gemini; if open, sets $json.gemini_open=true and $json.reply=<template>.
// The downstream IF node routes to Send Reply (open) or Complaint Agent (closed).
return [{ json: { ...$json, gemini_open: false } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/gemini-substitute.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Gemini Check - Blood' -> gemini-substitute.js)
// Task 27.4 — Design §v1.1.10 Circuit Breakers (Req 29.2, 29.3)
return [{ json: { ...$json, gemini_open: false } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/gemini-substitute.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Gemini Check - Donor' -> gemini-substitute.js)
// Task 27.4 — Design §v1.1.10 Circuit Breakers (Req 29.2, 29.3)
return [{ json: { ...$json, gemini_open: false } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/status-info.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Status Code' -> status-info.js)
// Also receives INFO_PROMPT + SCHEME_SUMMARIES prepended at deploy time.
const text = $json.message?.original_text || $json.message?.text || '';
return [{ json: { ...$json, reply: `Status check for: ${text}` } }];

// Welcome Code Node — greeting response
const reply = '🙏 নমস্কার! আমি সহায়ক (Sahayak)।

I can help you with:
1️⃣ File a complaint (অভিযোগ)
2️⃣ Request blood (রক্তের অনুরোধ)
3️⃣ Register as donor (দাতা নিবন্ধন)
4️⃣ Check complaint status
5️⃣ Scheme information

Please type your need or say Hi!';
return [{ json: { ...$json, reply } }];

// Fallback Code Node — Switch DEFAULT branch (Reliability NFR).
// Catches any CEO Router output that does not match the configured agents.
// Should never fire if Property 1 (CEO Router determinism) holds.
const reply = 'I\'m sorry, I didn\'t understand that. Please try again or type "Hi" to see available options.\n\nक्षमा करें, मैं समझ नहीं पाया। कृपया "Hi" लिखें।';
return [{ json: { ...$json, reply, reason: 'switch_default_fallback' } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/clarification-agent.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Clarification' -> clarification-agent.js)
// Clarification Micro-Agent (Design §v1.1.1, Req 20.5): runs when the Switch
// routes agent='clarification' (decideHybrid confidence < 0.6). Sends a
// localized WhatsApp interactive list and writes a routing_decisions row
// (reason='clarification_*'). Returns [{ json: { ...$json, reply, interactive } }].
return [{ json: { ...$json, reply: $json.reply || 'Please choose an option.', reason: 'clarification_sent' } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/guardrail.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Guardrail - Complaint' -> guardrail.js)
// Output Guardrail (Design §v1.1.6, Req 25): checks the Complaint Agent reply,
// repairs/substitutes as needed, logs non-OK actions to /api/guardrail/log.
return [{ json: { ...$json, guardrail_action: 'pass' } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/guardrail.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Guardrail - Blood' -> guardrail.js)
return [{ json: { ...$json, guardrail_action: 'pass' } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/guardrail.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Guardrail - Donor' -> guardrail.js)
return [{ json: { ...$json, guardrail_action: 'pass' } }];

// Fire Observability — async fire-and-forget logging AFTER the reply is sent.
// Logs BOTH a routing_decision and an agent_invocation to the JS-01v2-Observability
// sub-workflow webhook (which routes by 'kind' and writes to routing_decisions /
// agent_invocations). Decoupled from the reply path so observability cost cannot
// extend p95 reply latency (Req 18.14, 18.16, NFR Reliability).
//
// Routing context is read from the CEO Router node ($('CEO Router')) so the payload
// is correct regardless of which Switch branch (agent or code) actually ran.

const baseUrl = 'https://wb-grievance-portal.vercel.app';
const webhookPath = `${baseUrl}/webhook/js01v2-observability`;

let ctx = {};
try { ctx = $('CEO Router').first().json || {}; } catch (e) { ctx = $json || {}; }

const sessionId = ctx.phone || $json.phone || null;
const agent = ctx.agent || $json.agent || null;
const traceId = ctx.trace_id || $json.trace_id || null;
const messageText = (ctx.message?.text || $json.message?.text || '').substring(0, 200);
const lastIntentBefore = ctx.prev_last_intent || ctx.session?.last_intent || null;
const replyText = $json.reply || $json.output || '';

function fire(payload) {
  try {
    $http.request({
      method: 'POST',
      url: webhookPath,
      body: payload,
      json: true,
      timeout: 3000,
      headers: { 'Content-Type': 'application/json' }
    }).catch(() => { /* silent — observability failure is non-fatal */ });
  } catch (e) { /* silent — observability must never throw */ }
}

// 1) routing_decision log
fire({
  kind: 'routing_decision',
  payload: {
    session_id: sessionId,
    message_text: messageText,
    last_intent_before: lastIntentBefore,
    agent_dispatched: agent,
    reason: ctx.reason || $json.reason || '',
    trace_id: traceId
  }
});

// 2) agent_invocation log (Log to agent_invocations — task 7.2)
fire({
  kind: 'agent_invocation',
  payload: {
    session_id: sessionId,
    agent: agent,
    started_at: ctx.agent_started_at || null,
    completed_at: new Date().toISOString(),
    tokens_used: $json.tokenUsage?.totalTokens || null,
    tools_called: $json.tools_called || [],
    success: !!replyText,
    error_message: replyText ? null : 'empty_reply',
    trace_id: traceId
  }
});

// Return original $json unchanged so the workflow ends cleanly
return [{ json: $json }];
